146	function recordingFault(
147	  ctx: NodeContext<'inference'>,
148	  pending: PendingTurn,
149	  state: TurnFailures,
150	  operation: InferenceRecordingOperation,
151	  error: unknown,
152	): void {
153	  state.recording.push({ operation });
154	  ctx.ports.logger.error(
155	    {
156	      runId: ctx.run.id,
157	      nodeId: ctx.node.id,
158	      turnId: pending.turn.turnId,
159	      operation,
160	      error: errorDiagnostic(error),
161	    },
162	    'inference recording failed',
163	  );
164	}
165	function observe(state: TurnFailures, error: unknown): void {
166	  state.evidence = mergeHarnessFailure(state.evidence, harnessFailureEvidence(error));
167	}
