280	/** An explicitly returned native candidate stays authoritative, including undefined or null. */
281	function outputCandidate(result: HarnessResult): unknown {
282	  return Object.hasOwn(result, 'structured') ? result.structured : jsonOrText(result.finalText);
283	}
