285	function noteFor(item: HarnessItem): string | undefined {
286	  switch (item.type) {
287	    case 'command':
288	      return `Ran: ${item.summary}`;
289	    case 'file-change':
290	      return `Changed: ${item.summary}`;
291	    case 'tool-call':
292	      return `Tool: ${item.summary}`;
293	    default:
294	      return undefined;
295	  }
296	}
