298	export const inferenceHandler: NodeHandler<'inference'> = {
299	  kind: 'inference',
300	  async execute(ctx) {
301	    const { config } = ctx;
302	    const visit = visitTurn(await ctx.services.events(), ctx.node.id);
303	    let pending = visit.pending;
304	    if (pending?.submission === 'delivery-uncertain' && !canContinueTurn(pending))
305	      throw recoveryFailure(pending, ctx.node.id);
306	    const harness: HarnessPort | undefined = ctx.ports.harnesses[config.harness];
307	    const { model, effort } = await ctx.services.resolveModel(
308	      config.harness,
309	      visit.freshSession?.model ?? config.model,
310	      visit.freshSession?.effort ?? config.effort,
311	    );
312	    // Provenance comes from this run's open logical visit, never a session repository row.
313	    const missingFailure = (task?: PendingTurn): RunFailureError => {
314	      const origin: MissingSession['origin'] =
315	        (!task || (task.turn.promptKind === 'authored' && task.turn.resumeSessionId)) &&
316	        config.session.policy !== 'fresh'
317	          ? config.session.policy
318	          : 'current-visit';
319	      const sessionId = task?.sessionId ?? task?.turn.resumeSessionId;
320	      const missingSession: MissingSession = {
321	        visitId: visit.visitId,
322	        harness: config.harness,
323	        origin,
324	        model,
325	        effort,
326	        ...(sessionId ? { sessionId } : {}),
327	      };
328	      return new RunFailureError(
329	        'HARNESS_SESSION_MISSING',
330	        `The ${config.harness} session ${sessionId ? `"${sessionId}"` : '(no recorded handle)'} from ${origin} is missing. Choose Start fresh session for node "${ctx.node.id}" to continue without its prior provider conversation.`,
331	        {
332	          nodeId: ctx.node.id,
333	          resumable: false,
334	          missingSession,
335	          ...(task ? { inference: provenance(task) } : {}),
336	        },
337	      );
338	    };
339	    if (pending?.submission === 'session-missing') throw missingFailure(pending);
340	    const workingDirectory = nodeWorkingDirectory(
341	      await ctx.services.workingDirectory(),
342	      ctx.node.id,
343	    );
344	
345	    // Input transforms shape only the view the prompt sees; they are not persisted.
346	    const viewThread: ContextThread = config.input.length
347	      ? (
348	          await runMutations(ctx, ctx.thread, config.input, undefined, (fact, index, kind) =>
349	            transformFailure(ctx.node.id, 'inference.input', fact, index, kind),
350	          )
351	        ).thread
352	      : ctx.thread;
353	    const view = threadView(viewThread) as unknown as Record<string, unknown>;
354	
355	    for (const [fileIndex, file] of (config.contextFiles ?? []).entries()) {
356	      await ctx.ports.workspace.writeFile(
357	        workingDirectory,
358	        file.path,
359	        await renderAuthored(
360	          { nodeId: ctx.node.id, boundary: 'inference.contextFiles.template', fileIndex },
361	          file.template,
362	          view,
363	        ),
364	      );
365	    }
366	
367	    let resumeId: string | undefined;
368	    let prompt: string;
369	    let promptKind: PendingTurn['turn']['promptKind'] = 'authored';
370	    if (pending) {
371	      if (pending.submission === 'definitely-not-submitted') {
372	        prompt = pending.turn.prompt;
373	        promptKind = pending.turn.promptKind;
374	        resumeId = pending.turn.resumeSessionId;
375	      } else {
376	        resumeId = pending.sessionId;
377	        prompt = CONTINUATION_PROMPT;
378	        promptKind = 'continuation';
379	      }
380	    } else {
381	      prompt =
382	        visit.freshSession?.prompt ??
383	        (await renderAuthored(
384	          { nodeId: ctx.node.id, boundary: 'inference.prompt.template' },
385	          config.prompt.template,
386	          view,
387	        ));
388	      if (visit.freshSession) {
389	        // This explicit choice applies only to this logical visit; the authored policy stays.
390	        resumeId = undefined;
391	      } else if (config.session.policy === 'resume-previous') {
392	        resumeId = (await ctx.ports.sessions.latestWithSession(ctx.run.id, config.harness))
393	          ?.sessionId;
394	      } else if (config.session.policy === 'resume-named') {
395	        resumeId = (
396	          await ctx.ports.sessions.byScopeKey(
397	            `${ctx.thread.run.loopId}:${config.session.key}`,
398	            config.harness,
399	          )
400	        )?.sessionId;
401	      } else if (config.session.policy === 'resume-own' && visit.completedVisits > 0) {
402	        const reset = config.session.resetAfterVisits;
