426	        const window = await harness.contextWindow(
427	          {
428	            workingDirectory,
429	            model,
430	            effort,
431	            options: config.harnessOptions,
432	            ...(config.capabilities ? { capabilities: config.capabilities } : {}),
433	            turn: {
434	              prompt,
435	              ...(config.output.schema?.native
436	                ? { outputSchema: config.output.schema.jsonSchema }
