464	        if (error instanceof RunFailureError) throw error;
465	        throw mapHarnessFailure(error, undefined, ctx.node.id, config.harness).failure;
466	      }
467	    }
468	    const beginTurn = (
469	      text: string,
470	      kind: PendingTurn['turn']['promptKind'],
471	      id?: string,
472	    ): PendingTurn => {
473	      const turn = {
474	        visitId: visit.visitId,
475	        turnId: ctx.services.newId(),
476	        harness: config.harness,
477	        prompt: text,
478	        promptKind: kind,
479	        ...(admittedContext
480	          ? {
481	              context:
482	                kind === 'authored'
483	                  ? admittedContext
484	                  : { ...admittedContext, retainedHistoryPairs: 0, omittedHistoryPairs: 0 },
485	            }
486	          : {}),
487	        ...(id ? { resumeSessionId: id } : {}),
488	      };
489	      return {
490	        turn,
491	        submission: 'delivery-uncertain',
492	        accepted: false,
493	        ...(id ? { sessionId: id } : {}),
494	      };
495	    };
496	    const recordTurn = (task: PendingTurn) =>
497	      ctx.services.record({ type: 'harness.turn', nodeId: ctx.node.id, ...task.turn });
498	    // A safe retry retains the original turn identity and exact rendered prompt.
499	    if (!pending || pending.submission !== 'definitely-not-submitted') {
500	      pending = beginTurn(prompt, promptKind, resumeId);
501	      // A crash after this append may occur on either side of invocation: uncertain by default.
502	    } else {
503	      // Re-record the same task intent before another invocation. This resets any init-only ID
504	      // from the refused invocation, so a fresh retry cannot recover into that unused session.
505	      pending = {
506	        turn: pending.turn,
507	        submission: 'delivery-uncertain',
508	        accepted: false,
509	        ...(resumeId ? { sessionId: resumeId } : {}),
510	      };
511	    }
512	
513	    const row: HarnessSessionRecord = {
514	      runId: ctx.run.id,
515	      nodeId: ctx.node.id,
516	      attempt: ctx.attempt,
517	      harness: config.harness,
518	      status: 'starting',
519	      model,
520	      effort,
521	      updatedAt: ctx.services.now(),
522	      ...(resumeId ? { sessionId: resumeId } : {}),
523	      ...(config.session.policy === 'resume-named'
524	        ? { scopeKey: `${ctx.thread.run.loopId}:${config.session.key}` }
