528	    const turn: HarnessTurnRequest = {
529	      prompt,
530	      ...(schema?.native ? { outputSchema: schema.jsonSchema } : {}),
531	    };
532	    const sessionRequest = (next: HarnessTurnRequest): HarnessStartRequest => ({
