export class InMemoryEventStore implements EventStorePort {
  private readonly logs = new Map<string, RunEvent[]>();
  private readonly listeners = new Map<string, Set<(event: RunEvent) => void>>();
  constructor(
    private readonly clock: ClockPort,
    private readonly runRepository?: RunRepository,
  ) {}

  async append(
    runId: string,
    drafts: readonly EventDraft[],
    options: { expectedLastSeq?: number; requireRun?: boolean } = {},
  ): Promise<RunEvent[]> {
    if (options.requireRun && !(await this.runRepository?.get(runId))) return [];
    const log = this.logs.get(runId) ?? [];
    if (options.expectedLastSeq !== undefined && options.expectedLastSeq !== log.length) {
      return Promise.reject(new AppendConflictError(runId, options.expectedLastSeq, log.length));
    }
    const stored = drafts.map((draft, index) =>
      validateGeneratedEvent({
        ...draft,
        runId,
        seq: log.length + index + 1,
        ts: this.clock.now().toISOString(),
      }),
    );
    log.push(...stored);
    this.logs.set(runId, log);
    // SQLite publishes the tail with the events, before a delayed status projection.
    if (stored.length && (await this.runRepository?.get(runId)))
      await this.runRepository?.update(runId, { lastEventSeq: log.at(-1)!.seq });
    for (const event of stored) {
      for (const listener of this.listeners.get(runId) ?? []) listener(event);
    }
    return Promise.resolve(stored);
  }

  read(runId: string, afterSeq = 0, limit?: number): Promise<RunEvent[]> {
    const events = (this.logs.get(runId) ?? []).filter((e) => e.seq > afterSeq);
    return Promise.resolve(limit === undefined ? events : events.slice(0, limit));
  }

  recoveryFacts(
    runId: string,
    nodeIds: readonly string[],
  ): ReturnType<EventStorePort['recoveryFacts']> {
    const events = this.logs.get(runId) ?? [];
    return Promise.resolve({
      observedSeq: events.at(-1)?.seq ?? 0,
      lifecycle: events.findLast((e) =>
        [
          'run.failed',
          'run.finished',
          'run.cancelled',
          'run.started',
          'run.resumed',
          'run.paused',
        ].includes(e.type),
      ),
      failed: events.findLast((e) => e.type === 'run.failed'),
      resumed: events.findLast((e) => e.type === 'run.resumed'),
      reachedNodeIds: nodeIds.filter((id) =>
        events.some((e) => e.type === 'node.started' && e.nodeId === id),
      ),
    });
  }

  subscribe(runId: string, listener: (event: RunEvent) => void): () => void {
    const set = this.listeners.get(runId) ?? new Set();
    set.add(listener);
    this.listeners.set(runId, set);
    return () => {
      set.delete(listener);
    };
  }

  /** Admission installs the complete transaction before notifying subscribers. */
  commitQueued(event: RunEvent): void {
    this.logs.set(event.runId, [event]);
  }
  /** The next event of an existing log, validated but not yet installed (atomic admission). */
  prepareNext(runId: string, draft: EventDraft, ts: string): RunEvent {
    return validateGeneratedEvent({
      ...draft,
      runId,
      seq: (this.logs.get(runId)?.length ?? 0) + 1,
      ts,
    });
  }
  /** Install a prepared event of an existing log, without notifying (atomic admission). */
  commitNext(event: RunEvent): void {
    const log = this.logs.get(event.runId) ?? [];
    log.push(event);
    this.logs.set(event.runId, log);
  }
  notifyCommitted(event: RunEvent): void {
    for (const listener of this.listeners.get(event.runId) ?? []) {
      try {
        listener(event);
      } catch {
        /* A subscriber cannot undo a committed transaction. */
      }
    }
  }

  /** Test helper: synchronous read. */
  all(runId: string): RunEvent[] {
    return [...(this.logs.get(runId) ?? [])];
  }
}

